import fs from 'node:fs/promises';import path from 'node:path';import crypto from 'node:crypto';
const root=path.resolve('EVA_PRINT_WEBSITE_BRIEF_2026-10-02'),load=async p=>JSON.parse(await fs.readFile(path.join(root,p),'utf8'));
const materials=await load('02_MATERIALS/materials.en.json'),industries=await load('03_INDUSTRIES/industries.en.json'),cases=await load('03_INDUSTRIES/documented-external-cases.json'),assets=await load('07_DATABASE/asset-import-manifest.json');const failures=[];
for(const a of assets){const dest=path.resolve(root,a.path);if(!dest.startsWith(root+path.sep)){failures.push('Traversal: '+a.path);continue;}try{const b=await fs.readFile(dest);if(b.length!==a.bytes)failures.push('Length: '+a.path);if(crypto.createHash('sha256').update(b).digest('hex')!==a.hash)failures.push('Hash: '+a.path);if(a.kind.includes('pdf')&&b.subarray(0,5).toString()!=='%PDF-')failures.push('PDF signature: '+a.path);}catch(e){failures.push('Missing: '+a.path);}}
for(const m of materials){for(const rel of [m.engineering_overview,...Object.entries(m.drawings).filter(([k])=>['svg','png','pdf','dxf'].includes(k)).map(([,v])=>v),...m.datasheets.map(d=>d.path),...m.reference_photos.map(d=>d.path)]){try{await fs.access(path.join(root,rel));}catch(e){failures.push('Material link missing: '+rel);}}if(m.manufacturer_tds_status==='downloaded'&&!m.datasheets.some(d=>d.document_type==='TDS'))failures.push('False TDS status: '+m.id);}
for(const c of cases)for(const p of c.photos||[]){try{await fs.access(path.join(root,p.path));}catch(e){failures.push('Case photo missing: '+p.path);}}
const sorted=[...materials].sort((a,b)=>a.name.localeCompare(b.name,'en',{sensitivity:'base'}));if(sorted.some((m,i)=>m.id!==materials[i].id))failures.push('Alphabetical material order');
const missing=materials.filter(m=>m.manufacturer_tds_status!=='downloaded').map(m=>({id:m.id,name:m.name,source:m.source_url,status:'Exact manufacturer TDS PDF not retrieved; original EVA PRINT overview included separately.'}));await fs.writeFile(path.join(root,'12_VALIDATION/unavailable-manufacturer-tds.json'),JSON.stringify(missing,null,2));
const report={checked_at:'2026-10-02',asset_rows_checked:assets.length,total_asset_bytes:assets.reduce((s,a)=>s+a.bytes,0),material_pages_checked:materials.length,industry_pages:industries.length,external_cases:cases.length,missing_manufacturer_tds:missing.length,missing_exact_supplier_photo:materials.filter(m=>!m.reference_photos.length).map(m=>m.name),local_links_and_hashes:'checked',remote_link_scope:'Retrieved source pages and download outcomes are recorded in the source/download manifests. Availability may change; failed downloads are not counted as assets.',failures};await fs.writeFile(path.join(root,'12_VALIDATION/asset-validation.json'),JSON.stringify(report,null,2));console.log(JSON.stringify(report));if(failures.length)process.exitCode=1;
